{
  "items": [
    {
      "name": "sSup_image2",
      "module_name": "Mathlib.Order.CompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} [inst : CompleteLattice α] {f : β → γ → α} {s : Set β} {t : Set γ},\n  sSup (Set.image2 f s t) = ⨆ a ∈ s, ⨆ b ∈ t, f a b"
    },
    {
      "name": "iSup_prod'",
      "module_name": "Mathlib.Order.CompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} [inst : CompleteLattice α] (f : β → γ → α),\n  ⨆ i, ⨆ j, f i j = ⨆ x, f x.1 x.2"
    },
    {
      "name": "iSup_and'",
      "module_name": "Mathlib.Order.CompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteLattice α] {p q : Prop} {s : p → q → α},\n  ⨆ (h₁ : p), ⨆ (h₂ : q), s h₁ h₂ = ⨆ (h : p ∧ q), s ⋯ ⋯"
    },
    {
      "name": "iSup_prod",
      "module_name": "Mathlib.Order.CompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} [inst : CompleteLattice α] {f : β × γ → α}, ⨆ x, f x = ⨆ i, ⨆ j, f (i, j)"
    },
    {
      "name": "biSup_sigma'",
      "module_name": "Mathlib.Data.Set.Sigma",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_3} {β : Type u_4} [inst : CompleteLattice β] (s : Set ι) (t : (i : ι) → Set (α i))\n  (f : (i : ι) → α i → β), ⨆ i ∈ s, ⨆ j ∈ t i, f i j = ⨆ ij ∈ s.sigma t, f ij.fst ij.snd"
    }
  ]
}
